// SPDX-License-Identifier: MIT
// Generate packages/sdk/src/generated/* from protocol-inputs/contracts (see tools/inputs.mjs). Generated files are
// checked in, carry a header naming their inputs, and are never edited by hand.
//   node tools/codegen.mjs           write
//   node tools/codegen.mjs --check   fail if a regenerated file differs from the checked-in one
import { createHash } from "node:crypto";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fail, ok, ROOT } from "./lib/util.mjs";

const IN = join(ROOT, "protocol-inputs/contracts");
const OUT = join(ROOT, "packages/sdk/src/generated");
const check = process.argv.includes("--check");
const lock = JSON.parse(readFileSync(join(ROOT, "protocol-inputs/lock.json"), "utf8"));
const read = (p) => readFileSync(join(IN, p), "utf8");
const json = (p) => JSON.parse(read(p));
const sha = (s) => createHash("sha256").update(s).digest("hex").slice(0, 16);

/** The contracts the SDK calls, and the export names it uses for their ABIs. */
const ABIS = {
  ledgerAbi: "LedgerCore", // ILedger (execute) + ILedgerHot (nonceOf, publicationAt, executionSet, ...) at the proxy
  ingressAbi: "LedgerIngress", // acceptanceProfileOf, indexFloor, nativeIntentDigest
  ledgerReadsAbi: "LedgerReads",
  ledgerViewsAbi: "LedgerViews",
  lensReaderAbi: "LensReader",
  filesPageReaderAbi: "FilesPageReader",
};

function header(inputs) {
  return [
    "// SPDX-License-Identifier: MIT",
    "// GENERATED by tools/codegen.mjs. DO NOT EDIT. Regenerate with `pnpm generate`.",
    `// contracts ${lock.contracts.commit} · inputs: ${inputs.map((p) => `${p}@${lock.contracts.files[p]?.slice(0, 12) ?? "?"}`).join(", ")}`,
    "",
  ].join("\n");
}
const literal = (v) => JSON.stringify(v, null, 2);

const files = {};

// ---- ABIs (functions, events and errors exactly as compiled)
{
  const inputs = Object.values(ABIS).map((n) => `artifacts/${n}.json`);
  let src = header(inputs);
  for (const [exp, name] of Object.entries(ABIS)) {
    const abi = json(`artifacts/${name}.json`).abi;
    src += `/** ${name} ABI (${abi.length} entries). */\nexport const ${exp} = ${literal(abi)} as const;\n\n`;
  }
  // Every custom error across all artifacts, deduplicated by signature, for revert decoding.
  const seen = new Map();
  for (const f of Object.keys(lock.contracts.files).filter((p) => p.startsWith("artifacts/"))) {
    const artifact = json(f);
    if (!Array.isArray(artifact.abi)) continue; // e.g. an index file, not a compiled unit
    for (const e of artifact.abi.filter((x) => x.type === "error")) {
      const sig = `${e.name}(${e.inputs.map((i) => i.type).join(",")})`;
      if (!seen.has(sig)) seen.set(sig, e);
    }
  }
  const errors = [...seen.entries()].sort(([a], [b]) => (a < b ? -1 : 1)).map(([, e]) => e);
  src += `/** Every custom error any EFS contract can revert with (${errors.length}). */\nexport const errorAbi = ${literal(errors)} as const;\n`;
  files["abis.ts"] = src;
}

// ---- Domains, family ids, purposes (opaque protocol identity; never hand-typed)
{
  const ids = json("test/vectors/ids.json");
  let src = header(["test/vectors/ids.json"]);
  src +=
    "/** keccak256 domain tags used in id derivations (Keys.sol). Opaque protocol constants. */\n";
  src += `export const DOMAINS = ${literal(ids.domains)} as const;\n\n`;
  src += "/** Index family ids (Keys.familyId). */\n";
  src += `export const FAMILIES = ${literal(ids.families)} as const;\n\n`;
  src +=
    "/** Golden vectors for the key derivations (used by tests; tree-shaken from builds). */\n";
  src += `export const KEY_VECTORS = ${literal({ inputs: ids.inputs, outputs: ids.outputs })} as const;\n`;
  files["domains.ts"] = src;
}

// ---- Error catalog (meaning + retry class)
{
  const cat = json("release/errors.json");
  const rows = Object.entries(cat.errors).map(([selector, e]) => ({
    selector,
    name: e.name,
    signature: e.signature,
    retryClass: e.retryClass ?? null,
    meaning: e.meaning ?? null,
  }));
  let src = header(["release/errors.json"]);
  src +=
    "/** Contracts error catalog keyed by selector. retryClass null = not yet classified by contracts (C2). */\n";
  src += `export const ERROR_CATALOG: Readonly<Record<string, { name: string; signature: string; retryClass: string | null; meaning: string | null }>> = ${literal(Object.fromEntries(rows.map((r) => [r.selector, { name: r.name, signature: r.signature, retryClass: r.retryClass, meaning: r.meaning }])))};\n`;
  files["errors.ts"] = src;
}

// ---- Protocol inputs provenance (what this SDK build was generated from)
{
  let src = header([]);
  src += `export const PROTOCOL_INPUTS = ${literal({ contractsCommit: lock.contracts.commit, releaseDigest: lock.contracts.releaseDigest })} as const;\n`;
  files["inputs.ts"] = src;
}

mkdirSync(OUT, { recursive: true });
let drift = 0;
for (const [name, content] of Object.entries(files)) {
  const path = join(OUT, name);
  if (check) {
    const have = existsSync(path) ? readFileSync(path, "utf8") : null;
    if (have !== content) {
      fail(`generated/${name} is stale (run pnpm generate)`);
      drift++;
    }
  } else {
    writeFileSync(path, content);
  }
}
if (!drift)
  ok(
    `${check ? "checked" : "wrote"} ${Object.keys(files).length} generated files (${Object.entries(
      files,
    )
      .map(([n, c]) => `${n}:${sha(c)}`)
      .join(" ")})`,
  );
